(function() {
  window.CardSpoke.Plugin.register('focus-mode', {
    manifest: {
      name: 'Focus Mode',
      version: '1.0.0',
      author: 'CardSpoke Community',
      description: 'Hides distractions and enables a minimalist, distraction-free writing environment',
      layer: 'app',
      permissions: ['ui-override']
    },
    setup: async function(ctx) {
      var self = this;
      self._focusActive = false;
      var btn = document.createElement('button');
      btn.className = 'focus-mode-toggle';
      btn.textContent = '🎯 Focus Mode';
      btn.onclick = function() {
        self._focusActive = !self._focusActive;
        if (self._focusActive) {
          document.body.classList.add('focus-mode-active');
          btn.textContent = '✕ Exit Focus';
          ctx.logger.info('Focus mode enabled');
        } else {
          document.body.classList.remove('focus-mode-active');
          btn.textContent = '🎯 Focus Mode';
          ctx.logger.info('Focus mode disabled');
        }
      };
      document.body.appendChild(btn);
      self._toggleBtn = btn;
      var handleEscape = function(e) {
        if (e.key === 'Escape' && self._focusActive) {
          btn.click();
        }
      };
      document.addEventListener('keydown', handleEscape);
      self._handleEscape = handleEscape;
      ctx.logger.info('Focus Mode loaded');
    },
    teardown: async function(ctx) {
      document.body.classList.remove('focus-mode-active');
      if (this._toggleBtn && this._toggleBtn.parentNode) {
        this._toggleBtn.remove();
      }
      if (this._handleEscape) {
        document.removeEventListener('keydown', this._handleEscape);
      }
      ctx.logger.info('Focus Mode disabled');
    }
  });
})();
